public static boolean mustCreateRetailSalesTable()
{
    boolean ret = next mustCreateRetailSalesTable();

    ret = ret || GUPParameters::asRetailSalesOrder();

    return ret;
}

public boolean isGUPSalesOrder()
{
    boolean ret = false;

    if (GUPParameters::asRetailSalesOrder())
    {
        RetailSalesTable retailSalesTable = this.retailSalesTable();
        ret = retailSalesTable.RecId && retailSalesTable.ShouldUseUnifiedPricingEngineOnSalesOrder && !retailSalesTable.RetailChannel;
    }

    return ret;
}
